/*
 * A060138  Ordered set S defined by these rules: 0 and 2 are in S and if x is
 *          a nonzero number in S, then 2x-1 and 4x are in S.
 * https://oeis.org/A060138
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n-th element (0‑indexed) of the increasing *
 *            sequence obtained from the ordered set generated by: * start set
 *            S = {0, 2} * for every non‑zero x∈S, add 2x‑1 and 4x to S * The
 *            terms are returned in ascending order. No duplicate terms *
 *            occur
 * Range:     u8 n <= 21, u16 n <= 1153, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* ---------- global static state ---------- */
static seq_t *terms      = NULL;   /* cached terms, 0 indexed */
static idx_t  term_count = 0;      /* number of cached terms */
static idx_t  term_cap   = 0;      /* capacity of terms array */

static seq_t *heap       = NULL;   /* min‑heap of next candidates */
static idx_t  heap_size  = 0;      /* number of heap elements */
static idx_t  heap_cap   = 0;      /* heap capacity */

/* ---------- heap helpers ---------- */
static void heap_resize(idx_t new_cap)
{
    heap = (seq_t *)realloc(heap, new_cap * sizeof(seq_t));
    heap_cap = new_cap;
}

static void heap_push(seq_t v)
{
    if (heap_size + 1 > heap_cap) {
        idx_t new_cap = heap_cap ? heap_cap << 1 : 8;
        heap_resize(new_cap);
    }
    idx_t i = heap_size++;
    heap[i] = v;
    /* sift up */
    while (i > 0) {
        idx_t parent = (i - 1) >> 1;
        if (heap[i] < heap[parent]) {
            seq_t tmp = heap[i];
            heap[i] = heap[parent];
            heap[parent] = tmp;
            i = parent;
        } else break;
    }
}

static seq_t heap_pop(void)
{
    seq_t ret = heap[0];
    heap[0] = heap[--heap_size];
    /* sift down */
    idx_t i = 0;
    while (1) {
        idx_t left = (i << 1) + 1;
        idx_t right = left + 1;
        idx_t smallest = i;
        if (left < heap_size && heap[left] < heap[smallest])
            smallest = left;
        if (right < heap_size && heap[right] < heap[smallest])
            smallest = right;
        if (smallest == i) break;
        seq_t tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
    return ret;
}

/* ---------- main sequence function ---------- */
seq_t a(idx_t n)
{
    if (n == (idx_t)0) return (seq_t)0;   /* a(0)=0 */

    /* Initialise state if needed */
    if (terms == NULL) {
        terms = (seq_t *)malloc(8 * sizeof(seq_t));
        term_cap = 8;
        terms[0] = (seq_t)0;
        term_count = 1;               /* we have a(0) */
        /* initialise heap with first non‑zero generation */
        heap_reserve:
        heap = (seq_t *)malloc(8 * sizeof(seq_t));
        heap_cap = 8;
        heap_size = 0;
        heap_push((seq_t)2);          /* 2 is the first generated element */
    }

    /* Generate terms up to requested index n on demand */
    while (term_count <= n) {
        seq_t v = heap_pop();             /* next smallest element */
        if (term_count == term_cap) {
            term_cap <<= 1;
            terms = (seq_t *)realloc(terms, term_cap * sizeof(seq_t));
        }
        terms[term_count++] = v;          /* store a(term_count-1) */

        /* generate children of v (v is >0 because 0 was handled separately) */
        seq_t child1 = (seq_t)2 * v - 1;   /* 2v-1 */
        seq_t child2 = (seq_t)4 * v;       /* 4v */
        heap_push(child1);
        heap_push(child2);
    }

    return terms[n];
}
